function filter$syslog(p){
  this.constructor(p);
}
filter$syslog.prototype = new DirEvent();
filter$syslog.prototype.afterInit = function(){
  var p = this._dir;
}








declare @user_id int, @dateto datetime
if @username <> '' select @user_id = user_id from sysuserinfo where username = @username
set @dateto = convert(varchar(8), @ngay_ct2, 112) + ' 23:59:59'
select *, cast('' as nvarchar(256)) as ctext into #log from syslog where datetime0 between @ngay_ct1 and @dateto and (@username = '' or user_id = @user_id) order by datetime0 desc
update #log set ctext = case when '@@lan' = 'v' then b.text else b.text2 end from #log a join sysmenu b on a.xtype = b.controller
update #log set ctext = N'<b>'+ ctext + '</b>' where xtype like 'login%'
select a.ip, a.user_id, a.ctext, a.xtype, b.username, b.nickname, convert(char(19), a.datetime0, 120) as ctime from #log a left join sysuserinfo b on a.user_id = b.user_id
drop table #log
